from flask import Flask, render_template, request, redirect, url_for, session

app = Flask(__name__)
app.secret_key = 'your-secret-key'  # Change this to a secure random key in production

# Mock database of users
users_db = {
    'john_doe': {'password': 'password123', 'username': 'john_doe', 'email': 'john@example.com', 'ssn': '1234567890'},
    'jane_smith': {'password': 'securepass', 'username': 'jane_smith', 'email': 'jane@example.com', 'ssn': '0987654321'}
}

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        # Check if user exists and password matches
        if username in users_db and users_db[username]['password'] == password:
            session['username'] = username
            return redirect(url_for('info'))
        else:
            return render_template('login.html', error='Invalid username or password')

    return render_template('login.html')

@app.route('/info')
def info():
    if 'username' not in session:
        return redirect(url_for('login'))

    user = users_db[session['username']]
    # Show only the last 4 digits of the SSN
    ssn_last_4 = user['ssn'][-4:]

    return render_template('info.html', username=user['username'], email=user['email'], ssn_last_4=ssn_last_4)

if __name__ == '__main__':
    app.run(debug=True)

