import json
import os
from flask import Flask, jsonify

app = Flask(__name__)

# Đường dẫn đến file dữ liệu
FILE_PATH = 'info.json'

# Dữ liệu mặc định
DEFAULT_DATA = {
    "username": "guest",
    "email": "guest@example.com",
    "ssn": "1234567890"
}

def load_data():
    """Đọc dữ liệu từ file JSON, tạo file mới nếu không tồn tại."""
    if not os.path.exists(FILE_PATH):
        with open(FILE_PATH, 'w', encoding='utf-8') as f:
            json.dump(DEFAULT_DATA, f, indent=4)
        return DEFAULT_DATA
    else:
        with open(FILE_PATH, 'r', encoding='utf-8') as f:
            return json.load(f)

@app.route('/info')
def get_info():
    """Trả về dữ liệu người dùng dưới dạng JSON."""
    data = load_data()
    return jsonify(data)

if __name__ == '__main__':
    app.run(debug=True)
